"""Create local status/report/handoff only after actual execution and independent QA."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib, json, sys

ROOT=Path(__file__).resolve().parents[1]

def write_new(path,value):
    assert not path.exists(),f'Preserve {path}'
    path.write_text(value if isinstance(value,str) else json.dumps(value,indent=2)+'\n',encoding='utf-8')

def main():
    folder=(ROOT/Path(sys.argv[1])).resolve();assert folder.is_relative_to(ROOT/'results')
    r=json.loads((folder/'annual_sensitivity_v50.json').read_text())
    qp=sorted(folder.glob('independent_QA_v50_*.json'))[-1];q=json.loads(qp.read_text())
    assert r['summary']['harness_failed']==q['actual_failed']==q['reviewer_selfchecks_failed']==0
    assert r['summary']['completed_annual_scenarios']==9 and q['saved_intervals']==9*8760 and q['successful_receipts']
    stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S_%fZ');now=datetime.now(timezone.utc).isoformat()
    next_task=('Derive an additive time-varying TES delivery-cutoff interface Ec(k)=C*(Tdelivery(k)+approach-Ta) while retaining fixed tank heat capacity, ambient, 85C maximum/condenser and saved-v42 evidence. Audit verified primary thermal/HX evidence for finite approach and service-temperature definitions; any uncalibrated approach must be explicit engineering policy. Prove state continuity when cutoff changes, usable-inventory bounds, earliest cutoff events, dwell/event-budget behavior and first-law closure independently before building a new versioned Stateflow model. Start with component/probe tests and a matched multi-day sequence, then full annual comparison if admissible. Do not silently relabel a variable seasonal condenser as supported: charge-temperature/HX constraints need a separate interface and derivation. Primary equipment calibration, auxiliaries and measured physical validation remain open.')
    limits=[
        'Actual model remains saved release 0.42 with accepted SLX hash unchanged; 0.50 versions the executable sensitivity harness/report, not a new controller or SLX.',
        'Nine annual runs use identical synthetic deterministic source/load, zero initial energy and initial HP ON at age zero, fixed 85C condenser/tank maximum and 20C ambient. No measured calibration or equipment-specific primary validation.',
        'Every variant changes one cutoff/restart/ON-dwell/OFF-dwell parameter. Effects are conditional on this baseline/profile; interactions, joint sweeps, robustness to alternate weather/source/initial inventory and economic optimality are untested.',
        'Maximum usable discharge inventory is K-Ecut, not nominal 50MWh. Initial energy below cutoff is admissible but unusable until heated. Raising cutoff reduces usable inventory without changing tank capacity/heat capacity.',
        'Paired v48 is freshly executed MATLAB loss-first dispatch on the same HP source/load/lift; it lacks cutoff and latch/dwell and has different active-port integration. Differences against it combine policy and storage semantics, not numerical error.',
        'Annual modes are recorded per scenario. Six-mode acceptance is inherited from preserved v42/v49 fixtures; those fixtures were not rerun or claimed as six-mode annual coverage here.',
        'Physical events execute through up to64 bounded intra-macro Stateflow slots, not solver-clock event times. HP planning calls host MATLAB in normal mode; standalone generated-code deployment is not tested. ON dwell retains the accepted safety-OFF overrides.',
        'Independent QA is same-agent algorithmic/evidence review with Decimal closed-form HP roots/ODE and independent physical-span sums. It is not independent personnel, a universal floating-point proof, primary-paper replication or measured physical validation.',
        'Cost/CO2 compare equal actually delivered service with active HP/boiler only. Terminal inventory is explicitly reported but unpriced; auxiliaries, initial-inventory provenance/value, pumping, network transients, HX pinch, CAPEX and primary equipment maps remain unspecified.',
        'Original seasonal condenser/fixed-tank envelope remains unsupported as proved in v49. Fixed85C condenser with zero tank approach is a reduced synthetic boundary; the matrix does not remove that defect.',
        'MATLAB sandbox startup failed before executing project code; log/exit1 receipt retained. Local batch retry executed the matrix. Inherited Stateflow argument-shadow warnings remain. Full primary signoffs remain0/31; no new source-text claim.'
    ]
    s=dict(version='0.50',timestamp_utc=now,inherits='STATUS_v49.json',stateflow_inherits='STATUS_stateflow_v42.json',checkpoint='Matched one-parameter annual saved-Stateflow sensitivity matrix',result='PASS_SCOPED_ACTUAL_ANNUAL_SENSITIVITY',model_version='0.42',new_model=False,saved_model='matlab/simulink/DCHR_Dispatch_Stateflow_v42.slx',model_sha256=hashlib.sha256((ROOT/'matlab/simulink/DCHR_Dispatch_Stateflow_v42.slx').read_bytes()).hexdigest(),model_executed_this_run=True,completed_annual_scenarios=9,saved_model_intervals=q['saved_intervals'],positive_segments=q['positive_segments'],harness_passed=r['summary']['harness_passed'],harness_failed=0,independent_actual_passed=q['actual_passed'],independent_actual_failed=0,reviewer_selfchecks_passed=q['reviewer_selfchecks_passed'],reviewer_selfchecks_failed=0,matlab_version=r['metadata']['matlab_version'],stateflow_version=r['metadata']['stateflow_version'],stateflow_license_observed=bool(r['metadata']['stateflow_license_test']),matlab_batch_exit_code=0,result_directory=folder.relative_to(ROOT).as_posix(),independent_qa=qp.relative_to(ROOT).as_posix(),successful_receipts=q['successful_receipts'],preserved_artifacts=q['breakdown']['preservation'],max_independent_macro_residual_MWh=q['max_independent_macro_residual_MWh'],scenarios=q['scenarios'],matrix=r['matrix'],full_primary_signoffs=0,total_sources=31,primary_article_replication=False,independent_physical_validation='NOT_TESTED',limitations=limits,next_actionable_task=next_task)
    table='| Policy | Usable MWh | Unmet MWh | Delta vs baseline MWh | HP electricity MWh | Latch changes | Terminal MWh |\n|---|---:|---:|---:|---:|---:|---:|\n'
    for m in r['matrix']:
        table+=f'| {m["id"]} | {m["maximum_usable_inventory_MWh"]:.6f} | {m["unmet_MWh"]:.6f} | {m["unmet_delta_baseline_MWh"]:+.6f} | {m["hp_electric_MWh"]:.6f} | {m["latch_changes"]} | {m["terminal_inventory_MWh"]:.6f} |\n'
    paired=r['paired_report']['energy'];base=r['matrix'][0]
    observations=[]
    for m in r['matrix'][1:]:
        coordinate=next(x['changed_coordinate'] for x in r['stateflow'] if x['id']==m['id'])
        observations.append(f'{m["id"]} changes only {coordinate}: unmet delta {m["unmet_delta_baseline_MWh"]:+.6f} MWh; latch changes {m["latch_changes"]-base["latch_changes"]:+d}; terminal inventory delta {m["terminal_inventory_MWh"]-base["terminal_inventory_MWh"]:+.6f} MWh.')
    text=(f'# Matched annual Stateflow sensitivity results — v50\n\n{now}. Scoped executable implementation/experiment acceptance PASS.\n\n'
          f'Actual saved-v42 executions: nine independent full years, {q["saved_intervals"]} intervals, {q["positive_segments"]} positive physical segments. MATLAB {s["harness_passed"]}/0; independent actual {q["actual_passed"]}/0; {q["reviewer_selfchecks_passed"]} separately labelled reviewer mutation checks. All original SimulationOutputs/MATs reopened; numeric exports and stored reports matched. Baseline reproduces preserved v49. Maximum independent first-law residual {q["max_independent_macro_residual_MWh"]:.9g} MWh.\n\n'+table+
          '\nPolicy coordinates: baseline cutoff80C, restart48MWh, ON/OFF dwell0.25h; cutoff81/82C; restart47/49MWh; ON0/0.5h; OFF0/0.5h. Tank K=50MWh, C=10/13MWh/K, Tmax=condenser85C, Ta20C and initialE0 are held fixed. Each sensitivity row changes one coordinate.\n\n'+
          '\n'.join(observations)+f'\n\nFresh paired v48 loss-first annual unmet is {paired["unmet_heat_MWh"]:.6f} MWh, HP electricity {paired["hp_electric_MWh"]:.6f} MWh. Every scenario’s delta against it is saved in sensitivity_matrix.csv and independently checked. Those differences remain joint storage/controller-policy effects. Terminal inventory must not be converted into savings without a valuation/provenance boundary. Equal delivered-service energy/cost/CO2 reports are saved for each original trajectory.\n\n'+
          'Engineering decision: retain accepted saved-v42 dispatch and its numerical gates. The temperature/service boundary is an appropriate next interface study: the fixed cutoff reserves most of the nominal tank inventory across the year, and v49 independently rejects the native seasonal condenser mapping. These experiments support studying a delivery-dependent cutoff; they do not prove a corrected variable-temperature model or calibrated physical benefit. Keep tank heat capacity and maximum fixed so that changing a service cutoff cannot inject/remove thermal energy. A seasonal condenser needs separate charge/HX-temperature semantics.\n\n'+
          f'Evidence: {folder.relative_to(ROOT).as_posix()}; {qp.relative_to(ROOT).as_posix()}; timestamped execution logs/receipts, nine preflight tables, original simulation/adapter MATs, dispatch/segment/clock/port CSVs, sensitivity_matrix.csv and reports; source snapshots, reviewer snapshots and preservation manifest. {s["preserved_artifacts"]} prior artifact hashes and accepted SLX CRC/hash pass. Scope is same-agent independent numerical/evidence QA, not measured physical validation.\n\nLimitations:\n\n'+''.join('- '+v+'\n' for v in limits)+f'\nNext actionable task: {next_task}\n')
    write_new(ROOT/'STATUS_v50.json',s)
    write_new(ROOT/'audit/Annual_sensitivity_results_v50.md',text)
    write_new(ROOT/'MASTER_STAGEBOARD_v50.md',f'# v50 matched annual Stateflow handoff\n\n{now}. Nine matched saved-v42 annual sensitivity executions PASS; model remains0.42, no new SLX.\n\nMATLAB{s["harness_passed"]}/0; independent{q["actual_passed"]}/0; {q["reviewer_selfchecks_passed"]} separate reviewer mutations. {q["saved_intervals"]} actual intervals/{q["positive_segments"]} positive segments. Baseline reproduces v49; cutoff, restart and each dwell coordinate varied separately. Original MAT/SimulationOutputs reopened; model/prior evidence hashes preserved.\n\n'+table+f'\nEvidence: STATUS_v50.json; audit/Annual_sensitivity_derivation_v50.md; audit/Annual_sensitivity_results_v50.md; {folder.relative_to(ROOT).as_posix()}; {qp.relative_to(ROOT).as_posix()}.\n\nNext actionable task: {next_task}\n\nRun complete; stop with this handoff.\n')
    with (ROOT/'automation/engineering_progress.md').open('a',encoding='utf-8') as f:
        f.write(f'\n\n## {now} — v50 matched annual Stateflow sensitivity matrix\n\nRead latest STATUS/stageboard, STATEFLOW_ACCEPTANCE, research frontier, progress, annual adapter/reporting code, saved-v42 builder/planner/guards and inherited independent equations before edits. Existing versioned-model executable acceptance confirmed; followed v49 handoff.\n\nImplemented additive nine-case annual harness with one policy coordinate changed per variant, common synthetic source/load/lift/initial inventory, 8760-row preflight each, original SimulationOutputs and MAT reopening, integrated reports and sensitivity matrix. Independently verified each positive segment with closed-form Decimal HP/ODE/first-law equations, physical-span dwell/clock continuity, cutoff/capacity events, allocation/mode/limits, annual report totals, paired v48 recurrence, matched parameter design and v49 baseline reproduction.\n\n'+
                f'Pass/fail: MATLAB{s["harness_passed"]}/0; actual saved-v42 {q["saved_intervals"]} intervals/{q["positive_segments"]} positive segments across9 annual executions. Independent actual{q["actual_passed"]}/0 and {q["reviewer_selfchecks_passed"]} separate synthetic mutations. Max first-law residual{q["max_independent_macro_residual_MWh"]:.9g}MWh; {s["preserved_artifacts"]} prior artifact hashes plus accepted model hash/CRC intact.\n\nFiles created: matlab/run_annual_sensitivity_v50.m, matlab/export_annual_sensitivity_v50.m; audit/prepare_annual_sensitivity_v50.py, run_annual_sensitivity_v50.ps1, verify_annual_sensitivity_v50.py, finalize_annual_sensitivity_v50.py, check_annual_sensitivity_release_v50.py; v50 derivation/results/status/stageboard; timestamped spec/source/preservation evidence, logs/receipts, adapter/simulation MATs, preflight/dispatch/segment/clock/port CSVs, original MAT reopening, sensitivity matrix/reports and independent QA. Shared progress/acceptance ledgers appended only. No existing model, MATLAB component, historical evidence or data modified. No Jarvice/unrelated files, settings, scheduled tasks, agent runner, secrets or publication touched.\n\nFailures retained: initial sandbox MATLAB startup exit1 before project execution; identical local batch retry succeeds. Inherited Stateflow shadow warnings remain. Optional scipy import probe found package unavailable; no install/settings/dependency change, MATLAB reopening workflow used.\n\n'+table+'\nRemaining limitations:\n\n'+''.join('- '+v+'\n' for v in limits)+f'\nNext actionable task: {next_task}\nEvidence: {folder.relative_to(ROOT).as_posix()}; {qp.relative_to(ROOT).as_posix()}. Stop this coherent run with handoff.\n')
    with (ROOT/'automation/STATEFLOW_ACCEPTANCE.md').open('a',encoding='utf-8') as f:
        f.write(f'\n\n## Matched annual sensitivity acceptance — {now} / checkpoint v50\n\nSaved model remains0.42, no new SLX. Nine one-coordinate annual runs execute {q["saved_intervals"]} intervals/{q["positive_segments"]} positive segments. MATLAB{s["harness_passed"]}/0; independent actual{q["actual_passed"]}/0; {q["reviewer_selfchecks_passed"]} separate reviewer mutations. Baseline reproduces v49; cutoff/restart/ON/OFF dwell effects and terminal/usable inventory reported with original MAT/SimulationOutput reopening. STATUS_v50 and audit/Annual_sensitivity_results_v50.md authoritative. Synthetic implementation experiments only; primary equipment calibration/physical validation remain open. Next: derive delivery-dependent TES cutoff and separately resolve charge/condenser thermal semantics.\n')
    files=set(ROOT.glob('audit/*v50*'))|set(ROOT.glob('automation/logs/*v50*'))|{ROOT/'STATUS_v50.json',ROOT/'MASTER_STAGEBOARD_v50.md',ROOT/'matlab/run_annual_sensitivity_v50.m',ROOT/'matlab/export_annual_sensitivity_v50.m'}
    files.update(p for p in folder.rglob('*') if p.is_file() and 'local_build' not in p.parts)
    manifest=dict(timestamp_utc=now,excludes='Mutable append-only progress/acceptance ledgers and generated local_build caches.',files=[dict(path=p.relative_to(ROOT).as_posix(),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(files) if p.is_file()])
    mp=ROOT/'audit'/('Annual_sensitivity_manifest_v50_'+stamp+'.json');write_new(mp,manifest)
    print(json.dumps(dict(status='STATUS_v50.json',manifest=mp.relative_to(ROOT).as_posix(),sealed_files=len(manifest['files'])),indent=2))

if __name__=='__main__':main()
